async function createProject(page: Page) {
  const name = `E08 ${randomUUID().slice(0, 8)}`;
  await page.goto("/projects/new");
  await page.getByLabel("Nom du projet", { exact: true }).fill(name);
  await page.getByRole("button", { name: "Enregistrer le projet", exact: true }).click();
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();
  return name;
}
async function scopeUsage(page: Page, project: string) {
  const scope = page
    .getByRole("heading", { name: "Périmètre et période", exact: true })
    .locator("..");
  await scope
    .getByRole("combobox", { name: "Projet", exact: true })
    .selectOption({ label: project });
  await scope.getByRole("button", { name: "Appliquer les filtres", exact: true }).click();
}
