for (const refresh of [false, true])
  test(
    refresh
      ? "T-AC-817 refetch never silently rebases an old owner draft onto unseen budget policy"
      : "T-AC-817 real owner sees stale budget mutation failure instead of a false confirmation",
    async ({ page }) => {
      const project = await createProject(page);
      await page.goto("/usage");
      await scopeUsage(page, project);
      const form = page
        .getByRole("heading", { name: "Limites de consommation", exact: true })
        .locator("..");
      await form
        .getByRole("combobox", { name: "Projet", exact: true })
        .selectOption({ label: project });
      for (const [label, value] of [
        ["Plafond (µUSD)", "10000"],
        ["Fenêtre (secondes)", "60"],
        ["Exécutions par fenêtre", "5"],
        ["Exécutions simultanées", "1"],
      ] as const)
        await form.getByLabel(label, { exact: true }).fill(value);
      await form.getByRole("button", { name: "Enregistrer les limites", exact: true }).click();
      await expect(form.getByRole("status")).toBeVisible();
      await form
        .getByRole("combobox", { name: "Budget à modifier", exact: true })
        .selectOption({ index: 1 });
      const projectId = await form
        .getByRole("combobox", { name: "Projet", exact: true })
        .inputValue();
      const changed = await page.evaluate(
        async ({ header, version, projectId }) => {
          const headers = {
            "content-type": "application/json",
            [header]: version,
            "idempotency-key": crypto.randomUUID(),
          };
          const usage = await (
            await fetch(`/api/v1/usage?projectId=${projectId}`, { headers })
          ).json();
          const budget = usage.budgets[0];
          const response = await fetch("/api/v1/usage/budgets", {
            method: "PUT",
            headers,
            body: JSON.stringify({
              projectId: budget.projectId,
              scope: budget.scope,
              scopeId: budget.scopeId,
              expectedRevision: budget.revision,
              limitMicros: 9000,
              windowSeconds: budget.windowSeconds,
              maxRuns: budget.maxRuns,
              maxConcurrent: budget.maxConcurrent,
            }),
          });
          return response.status;
        },
        { header: CONTROL_API_HEADER, version: CONTROL_API_VERSION, projectId },
      );
      expect(changed).toBe(200);
      await form.getByLabel("Plafond (µUSD)", { exact: true }).fill("8000");
      if (refresh) {
        await page.getByRole("button", { name: "Actualiser la consommation", exact: true }).click();
        await expect(form.getByLabel("Plafond (µUSD)", { exact: true })).toHaveValue("9000");
        return;
      }
      await form.getByRole("button", { name: "Enregistrer les limites", exact: true }).click();
      await expect(form.getByRole("alert")).toBeVisible();
      await expect(form.getByRole("status")).toHaveCount(0);
    },
  );

test("T-AC-817 real owner inspects actual scoped telemetry and acknowledges its persisted incident", async ({
  page,
}, info) => {
  const projectName = await createProject(page),
    sourceName = `e08-positive-${randomUUID().slice(0, 8)}`;
  const seeded = await page.evaluate(
    async ({ projectName, sourceName, header, version }) => {
      const headers = { "content-type": "application/json", [header]: version };
      const status = await (await fetch("/api/v1/owner/session", { headers })).json();
      const projects = (await (await fetch("/api/v1/projects", { headers })).json()) as {
        id: string;
        name: string;
        environments: { id: string; kind: string }[];
      }[];
      const project = projects.find((project) => project.name === projectName),
        environment = project?.environments.find(
          (environment) => environment.kind === "development",
        );
      if (!project || !environment || !status.owner?.id)
        throw new Error("Actual owner source ancestry unavailable");
      const sourceResponse = await fetch("/api/v1/observability/sources", {
        method: "POST",
        headers: { ...headers, "idempotency-key": crypto.randomUUID() },
        body: JSON.stringify({
          name: sourceName,
          authenticatedActorId: status.owner.id,
          kind: "service",
          scope: { projectId: project.id, environmentId: environment.id, resourceId: null },
          staleAfterSeconds: 120,
        }),
      });
      if (!sourceResponse.ok) throw new Error(`Source refused ${sourceResponse.status}`);
      const source = await sourceResponse.json();
      const recordResponse = await fetch(`/api/v1/observability/sources/${source.id}/records`, {
        method: "POST",
        headers: { ...headers, "idempotency-key": crypto.randomUUID() },
        body: JSON.stringify({
          observedAt: new Date().toISOString(),
          state: "unavailable",
          event: "provider.unavailable",
          level: "error",
          code: "PROVIDER_OFFLINE",
          correlation: null,
          metrics: [{ name: "request.duration_ms", value: 123 }],
        }),
      });
      if (!recordResponse.ok) throw new Error(`Record refused ${recordResponse.status}`);
      return { sourceId: source.id };
    },
    { projectName, sourceName, header: CONTROL_API_HEADER, version: CONTROL_API_VERSION },
  );
  await page.goto("/observability");
  const filters = page
    .getByRole("heading", { name: "Périmètre des observations", exact: true })
    .locator("..");
  await filters
    .getByRole("combobox", { name: "Projet", exact: true })
    .selectOption({ label: projectName });
  await filters.getByRole("button", { name: "Appliquer les filtres", exact: true }).click();
  await expect(page.getByText(`${sourceName} · Indisponible`, { exact: true })).toBeVisible();
  const logs = page
    .getByRole("heading", { name: "Événements structurés", exact: true })
    .locator("..");
  await logs.locator("summary").filter({ hasText: "PROVIDER_OFFLINE" }).click();
  await expect(logs.getByText(`Source ${seeded.sourceId}`, { exact: false })).toBeVisible();
  await expect(logs.getByText("Corrélation : Aucune", { exact: true })).toBeVisible();
  const metrics = page
    .getByRole("heading", { name: "Mesures locales du contrôleur", exact: true })
    .locator("..");
  await metrics.locator("summary").first().click();
  await expect(metrics.getByText("request.duration_ms : 123", { exact: true })).toBeVisible();
  await page.getByRole("button", { name: "Réévaluer les incidents", exact: true }).click();
  const incident = page.getByRole("region", {
    name: `Incident Fournisseur ${projectName} · development`,
    exact: true,
  });
  await expect(
    incident.getByRole("heading", { name: `Fournisseur · ${seeded.sourceId}`, exact: true }),
  ).toBeVisible();
  await expect(incident.getByRole("status")).toHaveText(
    "Enregistré. Aucune notification externe n’est configurée.",
  );
  await incident.getByRole("button", { name: "Acquitter", exact: true }).click();
  await expect(incident.getByText("Acquitté", { exact: true })).toBeVisible();
  await page.screenshot({
    path: info.outputPath("observability-positive-evidence.png"),
    fullPage: true,
  });
});
